import pexpect
import sys

def run_cmd(cmd):
    child = pexpect.spawn(f'ssh -o StrictHostKeyChecking=no root@192.168.86.57 "{cmd}"', encoding='utf-8')
    try:
        idx = child.expect(['password:', pexpect.EOF, pexpect.TIMEOUT], timeout=10)
        if idx == 0:
            child.sendline('Malhi5$2')
            print(child.read())
        else:
            print(child.before)
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    run_cmd(sys.argv[1])

